<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetDisks, GetDiskPartitions } from '@wails/go/gui/App.js';
	// @ts-expect-error — generated by Wails
	import { LogInfo as WailsLogInfo, LogError as WailsLogError } from '@wails/runtime/runtime';

	function logInfo(msg: string): void {
		try { WailsLogInfo(msg); } catch { /* dev mode */ }
	}

	import PageLayout from '$components/PageLayout.svelte';
	import Button from '$components/Button.svelte';
	import { diskSelectionData, pageValid } from '$lib/state.svelte';
	import type { DiskInfo, PartitionDetail } from '$lib/types';
	import { formatSize, FILESYSTEMS } from '$lib/types';
	import { MinDiskSizeBytes } from '$lib/constants';
	import { t } from '$lib/i18n';

	let disks = $state<DiskInfo[]>([]);
	let partitions = $state<PartitionDetail[]>([]);
	let partitionsLoading = $state(false);
	let loading = $state(true);
	let error = $state<string | null>(null);
	let diskSizeError = $state<string | null>(null);
	let diskSizeErrorArgs = $state<{ minSize: string; selectedSize: string } | null>(null);

	async function loadDisks(): Promise<void> {
		try {
			disks = (await GetDisks()) ?? [];
		} catch (err) {
			error = `Failed to load disks: ${err instanceof Error ? err.message : String(err)}`;
			try { WailsLogError(`[DiskSelectionPage] ${error}`); } catch { /* dev mode */ }
		} finally {
			loading = false;
		}
	}

	async function selectDisk(disk: DiskInfo): Promise<void> {
		diskSelectionData.diskId = disk.path;
		diskSelectionData.disk = disk;
		logInfo(`[DiskSelectionPage] Selected: ${disk.path} (${formatSize(disk.size)})`);

		partitionsLoading = true;
		logInfo(`[DiskSelectionPage] Calling GetDiskPartitions for ${disk.path}`);
		partitions = [];
		try {
			const parts = await GetDiskPartitions(disk.path);
			logInfo(`[DiskSelectionPage] Got ${parts?.length ?? 0} partitions: ${JSON.stringify(parts)}`);
			partitions = parts ?? [];

			// Derive existing filesystem from partitions (root > largest ext4/btrfs > first with fstype)
			let existingFstype = disk.fstype;
			if (!existingFstype) {
				const rootPart = partitions.find((p) => p.mountpoints?.includes("/"));
				if (rootPart?.fstype) {
					existingFstype = rootPart.fstype;
				} else {
					const btrfsOrExt = partitions.find((p) => p.fstype === "btrfs" || p.fstype === "ext4");
					if (btrfsOrExt?.fstype) {
						existingFstype = btrfsOrExt.fstype;
					} else {
						const firstWithFs = partitions.find((p) => p.fstype);
						if (firstWithFs?.fstype) {
							existingFstype = firstWithFs.fstype;
						}
					}
				}
			}
			if (existingFstype && existingFstype !== disk.fstype) {
				disk.fstype = existingFstype;
				diskSelectionData.disk = { ...disk };
				logInfo(`[DiskSelectionPage] Derived existing fstype: ${existingFstype}`);
			}
		} catch (err) {
			logInfo(`[DiskSelectionPage] Failed to load partitions: ${err}`);
		} finally {
			partitionsLoading = false;
			logInfo(`[DiskSelectionPage] partitionsLoading=false, partitions.length=${partitions.length}`);
		}
	}

	loadDisks();

	$effect(() => {
		const disk = diskSelectionData.disk;
		const hasDisk = !!diskSelectionData.diskId;
		const hasFileSystem = !!diskSelectionData.fileSystem;
		
		// Check disk size
		if (disk && disk.size) {
			const sizeBytes = parseInt(disk.size, 10);
			if (!isNaN(sizeBytes) && sizeBytes < MinDiskSizeBytes) {
				diskSizeErrorArgs = {
					minSize: formatSize(String(MinDiskSizeBytes)),
					selectedSize: formatSize(disk.size),
				};
				diskSizeError = t('page.diskSelection.diskTooSmall', diskSizeErrorArgs);
				pageValid.value = false;
				return;
			}
		}
		
		diskSizeError = null;
		diskSizeErrorArgs = null;
		pageValid.value = hasDisk && hasFileSystem;
	});


</script>

<PageLayout title={t('page.diskSelection.title')} stretch={true}>
	<p class="hint">{t('page.diskSelection.hint')}</p>

	{#if loading}
		<div class="state-message">
			<div class="spinner"></div>
			<p>{t('page.diskSelection.loading')}</p>
		</div>
	{:else if error}
		<div class="state-message error">
			<p>{error}</p>
			<Button variant="secondary" onClick={loadDisks}>Retry</Button>
		</div>
	{:else if disks.length === 0}
		<div class="state-message">
			<p>{t('page.diskSelection.noDevices')}</p>
		</div>
	{:else}
		<div class="disk-page">
			<!-- Filesystem pills -->
			<div class="fs-bar">
				<span class="fs-label">{t('page.diskSelection.fileSystem')}</span>
				<div class="fs-pills">
					{#each FILESYSTEMS as fs (fs)}
						<button
							type="button"
							class={['fs-pill', { selected: diskSelectionData.fileSystem === fs }]}
							onclick={() => { diskSelectionData.fileSystem = fs; }}
						>
							{t('fs.' + fs)}
						</button>
					{/each}
				</div>
			</div>

			<!-- Disk size warning -->
				{#if diskSizeError}
					<div class="size-warning">
						<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
							<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
							<line x1="12" y1="9" x2="12" y2="13"/>
							<line x1="12" y1="17" x2="12.01" y2="17"/>
						</svg>
						<span>{diskSizeError}</span>
					</div>
				{/if}

			<!-- Disk cards -->
			<div class="disk-list">
				{#each disks as disk (disk.path)}
					<button
						type="button"
						class={['disk-card', { selected: diskSelectionData.diskId === disk.path }]}
						onclick={() => selectDisk(disk)}
						disabled={parseInt(disk.size, 10) < MinDiskSizeBytes}
					>
						<!-- Header: icon + name + radio -->
						<div class="card-header">
							<div class="disk-icon">
								{#if disk.rotational}
									<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
										<circle cx="12" cy="12" r="10"/>
										<circle cx="12" cy="12" r="3"/>
									</svg>
								{:else}
									<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
										<path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/>
									</svg>
								{/if}
							</div>
							<div class="card-title">
								<div class="disk-name">{disk.model || disk.name}</div>
								<div class="disk-specs">
									{formatSize(disk.size)}
									<span class="specs-sep">·</span>
									{t(disk.rotational ? 'disk.hdd' : 'disk.ssd')}
									{#if disk.trans}
										<span class="specs-sep">·</span>
										{disk.trans.toUpperCase()}
									{/if}
								</div>
							</div>
							<div class="card-radio">
								<div class={['radio', { checked: diskSelectionData.diskId === disk.path }]}></div>
							</div>
						</div>

						<!-- Inline tags (only shown when card is selected) -->
						{#if diskSelectionData.diskId === disk.path && (disk.fstype || disk.mountpoint)}
							<div class="card-tags">
								{#if disk.fstype}
									<span class="tag fstype">{t('disk.existing')} {disk.fstype}</span>
								{/if}
								{#if disk.mountpoint}
									<span class="tag mounted">{t('disk.mounted')} {disk.mountpoint}</span>
								{/if}
							</div>
						{/if}

						<!-- Partition details -->
						{#if diskSelectionData.diskId === disk.path}
							<div class="card-partitions">
								{#if partitionsLoading}
									<p class="partition-loading">{t('page.diskSelection.scanPartitions')}</p>
								{:else if partitions.length > 0}
									<table class="partition-table">
										<thead>
											<tr>
												<th>{t('disk.name')}</th>
												<th>{t('disk.type')}</th>
												<th class="text-right">{t('disk.size')}</th>
												<th class="text-right">{t('disk.mount')}</th>
											</tr>
										</thead>
										<tbody>
											{#each partitions as part (part.path)}
												<tr>
													<td class="part-name">{part.name}</td>
													<td>
														{#if part.fstype}
															<span class="part-fstype">{part.fstype}</span>
														{:else}
															<span class="part-unknown">—</span>
														{/if}
													</td>
													<td class="text-right">{formatSize(part.size)}</td>
													<td class="text-right">
														{#if part.mountpoints && part.mountpoints.length > 0}
															<span class="part-mount">{part.mountpoints.join(', ')}</span>
														{:else}
															<span class="part-empty">—</span>
														{/if}
													</td>
												</tr>
											{/each}
										</tbody>
									</table>
								{:else}
									<p class="partition-empty">{t('page.diskSelection.noPartitions')}</p>
								{/if}
							</div>
						{/if}
					</button>
				{/each}
			</div>
		</div>
	{/if}
</PageLayout>

